sql.where:
MP.post_status = 'active' AND MP.delete_yn = 0


  AND (
  MP.cate_code = #{categoryCode}
  OR MC.main_cate = #{categoryCode}
  )



  AND MP.deal_status IN('ON_SALE', 'IN_PROGRESS')



  AND MP.deal_status = 'SOLD'



  AND (
  MP.title LIKE CONCAT('%', #{keyword}, '%')
  OR MP.content LIKE CONCAT('%', #{keyword}, '%')
  )

mapper.select:
SELECT p.code, p.title, p.content, p.price, product_category.top_cate_code AS main_category_code, product_category.sub_cate_code AS sub_category_code, i.path AS image_paths FROM MARKET_PRODUCT AS p
JOIN ( SELECT top.code AS top_cate_code, sub.code AS sub_cate_code FROM MARKET_CATEGORY AS top, MARKET_CATEGORY AS sub WHERE top.code = sub.main_cate ) AS product_category ON product_category.sub_cate_code = p.cate_code
LEFT JOIN IMAGES i ON p.code = i.target_code AND i.type = 'market' WHERE p.code = #{prodCode} AND p.mem_code = #{memberCode}
